		        while (smallestNode._previous) {
		            //backtrack
		            const to = smallestNode.value,
		                parent = smallestNode._previous,
		                from = parent.value;

		            path.push(this.adjacencyList[from].find(x => x.target.value === to));
		            smallestNode = parent;
		        }

